-- 真实配对准备事实；日历显式配置，不生成胜负/奖励。
CREATE TABLE IF NOT EXISTS p13_union_fight_schedules (day VARCHAR(10) PRIMARY KEY,preparation_millis BIGINT NOT NULL DEFAULT 0,enabled BOOLEAN NOT NULL DEFAULT FALSE,version VARCHAR(64) NOT NULL DEFAULT '',published_at BIGINT NOT NULL DEFAULT 0,registration_day VARCHAR(10) NOT NULL DEFAULT '',enrollment_start_at BIGINT NOT NULL DEFAULT 0,enrollment_end_at BIGINT NOT NULL DEFAULT 0,first_start_at BIGINT NOT NULL,second_start_at BIGINT NOT NULL,duration_millis BIGINT NOT NULL,source TEXT NOT NULL, INDEX idx_p13_uf_calendar(enabled,enrollment_start_at), INDEX idx_p13_union_fight_schedules_registration_day(registration_day)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
